package org.jlinalg.cli;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import org.jlinalg.assembly.HifiasmGfa;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Actual original fields/exports plus scientific corruption/domain and immutable-identity controls. */
public final class HifiasmGfaAudit {
    private HifiasmGfaAudit(){ }
    private static int rejections;
    private static final HifiasmGfa.Limits LIMITS=new HifiasmGfa.Limits(268435456,67108864,1000000,100000,1000000,1000000,1000000000,1000000000);
    @FunctionalInterface private interface Rejection{void run()throws Exception;}
    private static void reject(Rejection action)throws Exception{try{action.run();}catch(IllegalArgumentException|java.io.IOException expected){rejections++;return;}throw new AssertionError("Malformed/corrupt graph family accepted");}
    private static List<String> tags(List<HifiasmGfa.Tag> tags){return tags.stream().map(t->t.name()+":"+t.type()+":"+t.value()).toList();}
    private static void optional(OptionalLong actual,Object expected)throws Exception{if(expected==null)require(actual.isEmpty(),"Invented absent source statistic");else require(actual.isPresent()&&actual.getAsLong()==integer(expected,0,Long.MAX_VALUE),"Exact integer graph statistic differs");}
    private static HifiasmGfa.Graph parse(String source)throws Exception{return HifiasmGfa.read(new ByteArrayInputStream(source.getBytes(StandardCharsets.UTF_8)),LIMITS);}
    public static void main(String[] args)throws Exception{
        require(args.length==3,"Require fixture, project root and NEW output");Path fixture=Path.of(args[0]).toAbsolutePath().normalize(),root=Path.of(args[1]).toAbsolutePath().normalize(),out=Path.of(args[2]).toAbsolutePath().normalize();require(!Files.exists(out),"Require NEW output");Files.createDirectory(out);var cases=list(GseapyExecutionRuntime.read(fixture,67108864).get("cases"));long segments=0,links=0,placements=0,numeric=0,diagnostics=0;int exported=0;
        for(Object raw:cases){var c=object(raw);Path file=root.resolve(text(c.get("path")));var expected=NextflowFiles.fingerprint(c.get("pin"),268435456);require(expected.equals(NextflowFiles.pin(file,268435456,()->{})),"Original graph changed before audit");HifiasmGfa.Graph graph;try(var stream=Files.newInputStream(file)){graph=HifiasmGfa.read(stream,LIMITS);}var rows=list(c.get("segments"));require(graph.segments().size()==rows.size(),"Complete original segment family changed");int at=0;for(var s:graph.segments().values()){var r=object(rows.get(at++));require(s.id().equals(text(r.get("id")))&&NextflowFiles.sha(s.sequence().getBytes(StandardCharsets.UTF_8)).equals(text(r.get("sequence_sha256")))&&s.length()==integer(r.get("length"),0,Long.MAX_VALUE)&&tags(s.tags()).equals(list(r.get("tags"))),"Original segment ID, full sequence, length or ordered tags differ");numeric++;}
            rows=list(c.get("links"));require(graph.links().size()==rows.size(),"Complete original link family changed");for(int i=0;i<rows.size();i++){var r=object(rows.get(i));var l=graph.links().get(i);require(l.from().equals(r.get("source"))&&Character.toString(l.fromStrand()).equals(r.get("source_strand"))&&l.to().equals(r.get("target"))&&Character.toString(l.toStrand()).equals(r.get("target_strand"))&&l.cigar().equals(r.get("cigar"))&&tags(l.tags()).equals(list(r.get("tags"))),"Directed original links/orientations/overlaps were changed");numeric+=l.overlap().isPresent()?1:0;}
            rows=list(c.get("placements"));require(graph.placements().size()==rows.size(),"Complete original read-placement family changed");for(int i=0;i<rows.size();i++){var r=object(rows.get(i));var a=graph.placements().get(i);require(a.segment().equals(r.get("segment"))&&a.offset()==integer(r.get("offset"),0,Long.MAX_VALUE)&&Character.toString(a.strand()).equals(r.get("strand"))&&a.read().equals(r.get("read"))&&a.gap()==bool(r.get("gap"))&&tags(a.tags()).equals(list(r.get("tags"))),"Original read-placement identities/order/source tags differ");optional(a.readStart(),r.get("start"));optional(a.readEnd(),r.get("end"));numeric+=3;}
            var stat=graph.statistics();var expectedStat=object(c.get("stats"));require(stat.segments()==integer(expectedStat.get("segments"),0,Long.MAX_VALUE)&&stat.sequenceBearingSegments()==integer(expectedStat.get("sequence_bearing"),0,Long.MAX_VALUE)&&stat.declaredBases()==integer(expectedStat.get("declared_bases"),0,Long.MAX_VALUE)&&stat.sequenceBases()==integer(expectedStat.get("sequence_bases"),0,Long.MAX_VALUE),"Complete original per-graph length family differs");optional(stat.maximumLength(),expectedStat.get("maximum"));optional(stat.n50(),expectedStat.get("n50"));optional(stat.l50(),expectedStat.get("l50"));var fasta=new ByteArrayOutputStream();var converted=HifiasmGfa.writeFasta(graph,fasta,60,true);var ef=object(c.get("fasta"));require(NextflowFiles.sha(fasta.toByteArray()).equals(ef.get("sha256"))&&fasta.size()==integer(ef.get("bytes"),0,Long.MAX_VALUE)&&converted.omitted().equals(list(ef.get("omitted"))),"Complete native FASTA differs from independent source extraction");require(NextflowFiles.sha((String.join("\n",graph.sourceLines())+(graph.sourceLines().isEmpty()?"":"\n")).getBytes(StandardCharsets.UTF_8)).equals(c.get("source_lines_sha256")),"Raw source record ordering/fields differ");require(expected.equals(NextflowFiles.pin(file,268435456,()->{})),"Original graph changed during audit");segments+=stat.segments();links+=stat.links();placements+=stat.placements();diagnostics+=graph.diagnostics().size();exported++;
        }
        String positive="H\tVN:Z:1.0\nS\tβ😀\tACgt\tLN:i:4\trd:i:0\nS\tx\t*\tLN:i:5\nL\tβ😀\t+\tβ😀\t+\t3M\tL1:i:1\nL\tβ😀\t-\tβ😀\t-\t7M\tL1:i:0\nA\tβ😀\t0\t+\tread\u2003literal\t1\t5\tid:i:0\tHG:A:a\nA\tβ😀\t2\t*\t*\t*\t*\tid:i:*\tHG:A:*\nA\tβ😀\t3\t+\tFAKE\t0\t1\tid:i:2\tHG:A:*\n";var graph=parse(positive);require(graph.links().get(0).overlap().orElseThrow()==3&&graph.links().get(1).overlap().orElseThrow()==7&&graph.placements().get(0).read().equals("read\u2003literal")&&graph.diagnostics().size()>=4,"Original directional/gap/virtual/source diagnostics changed");var before=new ByteArrayOutputStream();reject(()->HifiasmGfa.writeFasta(graph,before,60,false));require(before.size()==0,"Missing-sequence failure wrote earlier partial FASTA");var text=new ByteArrayOutputStream();var conversion=HifiasmGfa.writeFasta(graph,text,2,true);require(text.toString(StandardCharsets.UTF_8).equals(">β😀\nAC\ngt\n")&&conversion.omitted().equals(List.of("x")),"Unicode/case/missing sequence changed");
        for(String bad:List.of("S\tx\tA\tLN:i:2\n","S\tx\tA\n","S\tx\tA\tLN:i:1\nS\tx\tA\tLN:i:1\n","S\tx\tA\tLN:i:1\nL\tx\t+\ty\t+\t0M\n","S\tx\tA\tLN:i:1\nA\ty\t0\t+\tr\t0\t1\n","S\tx\tA\tLN:i:1\nL\tx\t?\tx\t+\t0M\n","S\tx\tA\tLN:i:1\nL\tx\t+\tx\t+\t1I\n","S\tx\tA\tLN:i:1\nA\tx\t0\t+\tr\t2\t1\n","S\tx\tA\tLN:i:1\tLN:i:1\n","P\tp\tx+\t*\n","S\tx y\tA\tLN:i:1\n","S\tx\tA\tLN:i:-1\n"))reject(()->parse(bad));reject(()->HifiasmGfa.read(new ByteArrayInputStream(new byte[]{'S','\t',(byte)255}),LIMITS));reject(()->HifiasmGfa.read(new ByteArrayInputStream(positive.getBytes(StandardCharsets.UTF_8)),new HifiasmGfa.Limits(1,1000,100,100,100,100,1000,1000)));reject(()->HifiasmGfa.read(new ByteArrayInputStream(positive.getBytes(StandardCharsets.UTF_8)),new HifiasmGfa.Limits(10000,2,100,100,100,100,1000,1000)));reject(()->new HifiasmGfa.Segment("x","β",1,List.of()));reject(()->new HifiasmGfa.Segment("\ud800","A",1,List.of()));reject(()->HifiasmGfa.writeFasta(graph,new ByteArrayOutputStream(),0,true));require(rejections==19,"Full malformed/corrupt/native-API rejection family differs");
        String large="S\ta\t*\tLN:i:9007199254740993\nS\tb\t*\tLN:i:9007199254740992\n";var big=HifiasmGfa.read(new ByteArrayInputStream(large.getBytes(StandardCharsets.UTF_8)),new HifiasmGfa.Limits(10000,1000,100,100,100,100,Long.MAX_VALUE,Long.MAX_VALUE));require(big.statistics().n50().orElseThrow()==9007199254740993L&&big.statistics().l50().orElseThrow()==1&&big.statistics().declaredBases()==18014398509481985L,"N50 lost exact integer precision above2^53");var empty=parse("");require(empty.statistics().n50().isEmpty()&&empty.statistics().l50().isEmpty(),"Empty assembly acquired inferred statistics");NextflowFiles.writeJson(out.resolve("COMPLETED.json"),Map.ofEntries(Map.entry("status","passed-complete-retained-original-GFA-and-native-FASTA-component-only"),Map.entry("graph_views",cases.size()),Map.entry("segments",segments),Map.entry("links",links),Map.entry("placements",placements),Map.entry("numeric_states",numeric),Map.entry("source_diagnostics",diagnostics),Map.entry("complete_FASTA_exports",exported),Map.entry("invalid_families_rejected",rejections),Map.entry("original_batch_relabelled",false),Map.entry("full_adapter_admitted",false),Map.entry("analysis_admitted",false)));System.out.println("Passed "+cases.size()+" complete graph views, "+links+" directed links, "+placements+" read placements and "+exported+" native FASTA exports;19 rejections");
    }
}
